import { capText, encodeEvent, parseCommand, projectTurn, ProtocolError, toolSubject, toolSummary, MAX_TEXT_FIELD } from "../src/protocol.js";
import type { TurnResult } from "../src/core/turn.js";

describe("protocol: encodeEvent", () => {
